<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Edit3, Heart, Plus, UserRound } from 'lucide-vue-next'
import { claimApi, itemApi, lostFoundApi } from '@/api'
import type { Claim, Item, LostFound } from '@/types'
import { formatMoney, formatTime } from '@/utils/format'
import StatusTag from '@/components/StatusTag.vue'
const tab=ref('items');const loading=ref(true);const items=ref<Item[]>([]);const lost=ref<LostFound[]>([]);const claims=ref<Claim[]>([])
async function load(){loading.value=true;try{const [a,b,c]=await Promise.all([itemApi.mine({page:1,size:50}),lostFoundApi.mine({page:1,size:50}),claimApi.mine({page:1,size:50})]);items.value=a.records;lost.value=b.records;claims.value=c.records}finally{loading.value=false}}
async function itemStatus(id:number,status:string,label:string){await ElMessageBox.confirm(`确认更新为“${label}”吗？`,'更新状态',{type:'warning'});await itemApi.status(id,status);ElMessage.success('状态已更新');load()}
async function lostStatus(id:number,status:string,label:string){await ElMessageBox.confirm(`确认更新为“${label}”吗？`,'更新状态',{type:'warning'});await lostFoundApi.status(id,status);ElMessage.success('状态已更新');load()}
onMounted(load)
</script>
<template><div><div class="page-heading"><div><h1>个人中心</h1><p>集中管理发布内容与认领进度</p></div><el-button @click="$router.push('/profile')"><UserRound :size="17" />编辑资料</el-button></div><div class="user-layout"><nav class="surface user-menu"><a :class="{ 'router-link-active':tab==='items' }" @click="tab='items'">我的商品</a><a :class="{ 'router-link-active':tab==='lost' }" @click="tab='lost'">我的失物信息</a><a :class="{ 'router-link-active':tab==='claims' }" @click="tab='claims'">我的认领</a><RouterLink to="/favorites"><Heart :size="15" />我的收藏</RouterLink><RouterLink to="/reports">我的举报</RouterLink></nav><section class="surface table-surface" v-loading="loading"><div class="data-toolbar"><strong>{{ tab==='items'?'我的商品':tab==='lost'?'我的失物信息':'我的认领申请' }}</strong><el-button v-if="tab!=='claims'" type="primary" size="small" @click="$router.push(tab==='items'?'/market/publish':'/lost-found/publish')"><Plus :size="15" />发布</el-button></div><el-table v-if="tab==='items'" :data="items"><el-table-column prop="title" label="商品" min-width="180" /><el-table-column label="价格" width="100"><template #default="{row}">{{ formatMoney(row.price) }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><StatusTag :status="row.status" /></template></el-table-column><el-table-column label="更新时间" width="145"><template #default="{row}">{{ formatTime(row.updateTime) }}</template></el-table-column><el-table-column label="操作" min-width="230" fixed="right"><template #default="{row}"><el-button text type="primary" @click="$router.push(`/market/${row.id}/edit`)"><Edit3 :size="14" />编辑</el-button><el-button v-if="row.status==='ON_SALE'" text @click="itemStatus(row.id,'TRADING','交易中')">交易中</el-button><el-button v-if="['ON_SALE','TRADING'].includes(row.status)" text @click="itemStatus(row.id,'SOLD','已售出')">售出</el-button><el-button v-if="['ON_SALE','TRADING'].includes(row.status)" text @click="itemStatus(row.id,'OFF_SHELF','已下架')">下架</el-button></template></el-table-column></el-table><el-table v-else-if="tab==='lost'" :data="lost"><el-table-column prop="title" label="标题" min-width="180" /><el-table-column label="类型" width="80"><template #default="{row}">{{ row.type==='LOST'?'寻物':'招领' }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><StatusTag :status="row.status" /></template></el-table-column><el-table-column prop="location" label="地点" min-width="130" /><el-table-column label="操作" min-width="220" fixed="right"><template #default="{row}"><el-button text type="primary" @click="$router.push(`/lost-found/${row.id}/edit`)">编辑</el-button><el-button v-if="row.status==='IN_PROGRESS'" text @click="lostStatus(row.id,'PROCESSING','处理中')">处理</el-button><el-button v-if="['IN_PROGRESS','PROCESSING'].includes(row.status)" text @click="lostStatus(row.id,row.type==='LOST'?'FOUND':'RETURNED',row.type==='LOST'?'已找回':'已归还')">完成</el-button><el-button v-if="['IN_PROGRESS','PROCESSING'].includes(row.status)" text @click="lostStatus(row.id,'CLOSED','已关闭')">关闭</el-button></template></el-table-column></el-table><el-table v-else :data="claims"><el-table-column prop="lostFoundTitle" label="认领信息" min-width="180"><template #default="{row}">{{ row.lostFoundTitle || `失物 #${row.lostFoundId}` }}</template></el-table-column><el-table-column prop="message" label="认领说明" min-width="180" show-overflow-tooltip /><el-table-column label="状态" width="100"><template #default="{row}"><StatusTag :status="row.status" /></template></el-table-column><el-table-column prop="reviewNote" label="审核备注" min-width="160"><template #default="{row}">{{ row.reviewNote || '--' }}</template></el-table-column><el-table-column label="申请时间" width="145"><template #default="{row}">{{ formatTime(row.createTime) }}</template></el-table-column></el-table><el-empty v-if="!loading&&((tab==='items'&&!items.length)||(tab==='lost'&&!lost.length)||(tab==='claims'&&!claims.length))" description="这里暂时没有记录" /></section></div></div></template>
